sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    try {
        gs.info("[Set Country Dynamic] Starting for record: " + (current.number || "new record"));

        // Skip if country is already set
        if (!current.country.nil()) {
            gs.info("[Set Country Dynamic] Country already set to: " + current.country.getDisplayValue());
            return;
        }

        // Get requester details
        var userId = current.requested_by;
        if (userId.nil()) {
            gs.info("[Set Country Dynamic] No requested_by set");
            return;
        }

        var userGR = new GlideRecord('sys_user');
        if (userGR.get(userId)) {
            gs.info("[Set Country Dynamic] Found user: " + userGR.name);

            // Try to get country from location reference
            if (!userGR.location.nil()) {
                gs.info("[Set Country Dynamic] User has location reference: " + userGR.location);

                var locationGR = new GlideRecord('cmn_location');
                if (locationGR.get(userGR.location)) {
                    gs.info("[Set Country Dynamic] Found location: " + locationGR.name);

                    // Check if location has direct country reference
                    if (!locationGR.country.nil()) {
                        gs.info("[Set Country Dynamic] Location has country reference: " + locationGR.country);
                        current.country = locationGR.country;
                        gs.info("[Set Country Dynamic] Set country from location's country reference");
                    } else {
                        gs.info("[Set Country Dynamic] Location has no country reference");

                        // Try to determine from location name/city
                        var locationName = locationGR.name ? locationGR.name.toString().toLowerCase() : '';
                        var locationCity = locationGR.city ? locationGR.city.toString().toLowerCase() : '';

                        if (locationName.indexOf('brasilia') > -1 || locationCity.indexOf('brasilia') > -1) {
                            setCountryByName(current, 'Brazil');
                        } else {
                            // Use default
                            setDefaultCountry(current);
                        }
                    }
                } else {
                    gs.info("[Set Country Dynamic] Could not find location record");
                    setDefaultCountry(current);
                }
            } else {
                gs.info("[Set Country Dynamic] User has no location set");
                setDefaultCountry(current);
            }

            // Set approver if not already set
            if (current.approver.nil() && !userGR.manager.nil()) {
                current.approver = userGR.manager;
                gs.info("[Set Country Dynamic] Set approver to: " + userGR.manager.getDisplayValue());
            }
        } else {
            gs.info("[Set Country Dynamic] Could not find user record");
            setDefaultCountry(current);
        }
    } catch (e) {
        gs.error("[Set Country Dynamic] Error: " + e);
    }

    // Helper function to set country by name
    function setCountryByName(record, countryName) {
        var countryGR = new GlideRecord('core_country');
        countryGR.addQuery('name', countryName);
        countryGR.query();

        if (countryGR.next()) {
            record.country = countryGR.sys_id;
            gs.info("[Set Country Dynamic] Set country to: " + countryName);
            return true;
        } else {
            gs.info("[Set Country Dynamic] Country not found in core_country table: " + countryName);

            // Try with alternate spelling (Brasil vs Brazil)
            if (countryName == 'Brazil') {
                countryGR = new GlideRecord('core_country');
                countryGR.addQuery('name', 'Brasil');
                countryGR.query();

                if (countryGR.next()) {
                    record.country = countryGR.sys_id;
                    gs.info("[Set Country Dynamic] Set country to Brasil (alternate spelling)");
                    return true;
                }
            }

            return false;
        }
    }

    // Helper function to set default country (India)
    function setDefaultCountry(record) {
        setCountryByName(record, 'India');
    }
})(current, previous);
